-- V12: Fix corrupted test cases, in-place expected outputs, and missing starter codes across all 250 problems
BEGIN;

-- 1. Remove manual dummy test problem if present
DELETE FROM test_cases WHERE problem_id IN (SELECT id FROM problems WHERE slug = 'test-them');
DELETE FROM submissions WHERE problem_id IN (SELECT id FROM problems WHERE slug = 'test-them');
DELETE FROM problems WHERE slug = 'test-them';

-- 2. Seed missing starter_code for 7 problems
UPDATE problems SET starter_code = '{"cpp": "class Solution {\npublic:\n    string encode(vector<string>& strs) {\n        \n    }\n\n    vector<string> decode(string s) {\n        \n    }\n};", "java": "class Solution {\n    public String encode(List<String> strs) {\n        \n    }\n\n    public List<String> decode(String str) {\n        \n    }\n}", "python": "class Solution:\n    def encode(self, strs: List[str]) -> str:\n        \n\n    def decode(self, s: str) -> List[str]:\n        "}' WHERE slug = 'encode-and-decode-strings';
UPDATE problems SET starter_code = '{"cpp": "class Solution {\npublic:\n    void wallsAndGates(vector<vector<int>>& rooms) {\n        \n    }\n};", "java": "class Solution {\n    public void wallsAndGates(int[][] rooms) {\n        \n    }\n}", "python": "class Solution:\n    def wallsAndGates(self, rooms: List[List[int]]) -> None:\n        \"\"\"\n        Do not return anything, modify rooms in-place instead.\n        \"\"\"\n        "}' WHERE slug = 'walls-and-gates';
